const ACTOR_ID = 'qnqksdshiMNdwqcrG';
const BUILD_ID = 'Hy2htFWnbJcwLiyHl';
const BUILD_TAG = 'temu-release-20260906d';
const COLUMNS = ['upsertKey','goodsId','title','region','currency','price','previousPrice','changeType','changedFields','availability','productUrl','observedAt','coverageStatus','stateAction','estimatedActorChargeUsd','runUrl'];

function preflight(config) {
  const ids=String(config.productIds??'').split(/[\s,]+/).filter(Boolean);
  if(!ids.length||ids.length>5||ids.some(id=>!/^\d{10,20}$/.test(id))||new Set(ids).size!==ids.length) throw Error('Enter one to five distinct Temu goods IDs.');
  if(!['us','uk','de','fr','es','it','nl','au','ca','br','mx','jp','pl','se','at','be','pt','cz','ie'].includes(config.region)) throw Error('Choose a supported market.');
  if(!/^[A-Za-z0-9_-]{20,}$/.test(config.spreadsheetId??'')||/REPLACE/.test(config.spreadsheetId)) throw Error('Set your Google spreadsheet ID before running.');
  if(!String(config.sheetName??'').trim()||! /^[A-Za-z0-9._~-]{1,64}$/.test(config.stateNamespace??'')) throw Error('Set a Sheet tab and stable monitoring scope.');
  const cap=Number(config.maxCostPerRunUsd);
  if(!Number.isFinite(cap)||cap<0.01||cap>0.5) throw Error('Actor charge cap must be between $0.01 and $0.50.');
  return {...config,ids:ids.sort(),maxCostPerRunUsd:cap,actorInput:{workflow:'track_product_changes',productIds:ids.sort(),searchKeywords:[],region:config.region,stateNamespace:config.stateNamespace,includeUnchanged:true,includeVariants:true,includeSummary:false,outputFormat:'default',maxBuyerChargeUsd:cap}};
}

function classify(response,now=Date.now()) {
  const run=response.data??response;
  if(!run.id||run.actId!==ACTOR_ID||run.buildId!==BUILD_ID) throw Error('Actor or immutable build mismatch.');
  if(['FAILED','TIMED-OUT','ABORTED'].includes(run.status)) throw Error(`Actor ${run.status}: https://console.apify.com/actors/runs/${run.id}. No Sheet write.`);
  if(!['READY','RUNNING','SUCCEEDED'].includes(run.status)) throw Error('Unexpected Actor state.');
  if(run.status!=='SUCCEEDED' && (!Number.isFinite(Date.parse(run.startedAt))||now-Date.parse(run.startedAt)>360000)) throw Error('Actor wait exceeded six minutes. Inspect the existing run; do not automatically start another.');
  if(run.status==='SUCCEEDED'&&(!run.defaultDatasetId||!run.defaultKeyValueStoreId)) throw Error('Successful run is missing output storage.');
  return {run,ready:run.status==='SUCCEEDED'};
}

function reconcile({config,run,summary,rows}) {
  if(summary.status!=='COMPLETED'||summary.workflow!=='track_product_changes') throw Error('No valid monitoring output.');
  if(summary.coverageStatus!=='COMPLETE'||summary.state?.committed!==true) throw Error('Monitoring coverage or state is incomplete; Sheet left unchanged.');
  const expected=Number(summary.delivered?.paidRows)+Number(summary.delivered?.freeRows);
  if(!Number.isInteger(expected)||expected<1||expected>100||rows.length!==expected) throw Error('Dataset row count does not match authoritative output.');
  const counts=summary.buyerCharge?.acceptedEvents,prices=run.pricingInfo?.pricingPerEvent?.actorChargeEvents;
  if(!counts||!prices) throw Error('Actor event estimate evidence missing.');
  let charge=0;
  for(const [event,count] of Object.entries(counts)) {
    if(!Number.isInteger(count)||count<0) throw Error('Invalid accepted event count.');
    if(count){const price=prices[event]?.eventPriceUsd;if(!Number.isFinite(price)||price<0) throw Error('Exact effective event price missing.');charge+=count*price;}
  }
  // Apify's final response can precede its billing counter update. Estimate
  // from the Actor's accepted events and this run's prices; never call it an invoice.
  for(const [event,count] of Object.entries(run.chargedEventCounts??{})) if(!Number.isInteger(count)||count<0||count>Number(counts[event]??0)) throw Error('Unreconciled platform event.');
  charge=Number(charge.toFixed(12));if(charge>config.maxCostPerRunUsd+1e-9) throw Error('Actor charge exceeded configured cap.');
  const products=new Map(),changes=new Map();
  const idOf=row=>{const id=String(row.goodsId??row.productId??String(row.stableId??'').replace(/^temu-product:/,''));if(!config.ids.includes(id)) throw Error('Output has an unexpected goods ID.');return id;};
  for(const row of rows){
    if(row.recordType==='product'){const id=idOf(row);if(products.has(id)) throw Error('Duplicate product snapshot.');products.set(id,row);}
    else if(row.recordType==='change'){const id=idOf(row);if(changes.has(id)||!['NEW','UPDATED','ENDED'].includes(row.changeType))throw Error('Invalid or duplicate change.');changes.set(id,row);}
    else if(!['coverage','summary'].includes(row.recordType)) throw Error('Unexpected record type.');
  }
  // Exact-target monitoring requires one current snapshot or a proven ENDED event per requested ID.
  // An unconfirmed disappearance leaves the entire Sheet untouched rather than pretending no change.
  return config.ids.map(id=>{
    const change=changes.get(id),product=products.get(id)??change?.after;
    if(!product && change?.changeType!=='ENDED')throw Error('Requested product has no verified snapshot or confirmed end.');
    const current=product??{},previous=change?.before??{};
    const baseline=summary.state.action==='BASELINE_CREATED';
    const type=change?.changeType??(baseline?'BASELINE':'UNCHANGED');
    const scope=[config.stateNamespace,config.region,...config.ids].join('|');
    return {upsertKey:`temu|${scope}|${id}`,goodsId:id,title:current.title??previous.title??'',region:config.region,currency:current.currency??'',price:current.price??'',previousPrice:type==='UPDATED'?previous.price??'':'',changeType:type,changedFields:(change?.changedFields??[]).join(', '),availability:type==='ENDED'?'ENDED':current.availability??'',productUrl:current.canonicalUrl??current.sourceUrl??`https://www.temu.com/g-${id}.html`,observedAt:summary.completedAt,coverageStatus:summary.coverageStatus,stateAction:summary.state.action,estimatedActorChargeUsd:charge,runUrl:`https://console.apify.com/actors/runs/${run.id}`};
  });
}

return [{json:preflight($input.first().json)}];

